$('start').onclick=begin;$('retry').onclick=begin;$('restart').onclick=begin;$('resume').onclick=lock;$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'SOUND OFF':'SOUND ON';};
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(mode==='playing')pause();return;}if(mode!=='playing')return;keys.add(e.code);if(e.code==='Space')shoot();if(e.code==='KeyR')reloadGun();});addEventListener('keyup',e=>keys.delete(e.code));
